#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/control/shared_capabilities/shared_capabilities.hpp"
#include "gui_forms/types.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// RichTextBox's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/rich_text_box.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// The plain text (Text): the source's blocks with the markup removed, joined by line feeds (markdown_plain_text); a view onto the parsed document. A write replaces the document with markdown that reads back as that text (punctuation escaped, each line feed a hard line break; leading white space on a line and trailing line feeds are not kept), clears the history and raises content_changed, text_changed when the plain text changes, then selection_changed. Throws std::invalid_argument for invalid UTF-8 and std::length_error past maximum_bytes.
template <typename Declaring>
struct RichTextBoxTextCapability {
    PropertyView<std::string, RichTextBoxTextCapability<Declaring>> text;

    static void assign(RichTextBoxTextCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.text), std::move(incoming));
    }

    static std::string read(const RichTextBoxTextCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::string current = control.read_view(capability.text);
        return current;
    }
};

// Whether the user may select and copy but not change the document (ReadOnly); a view onto the editing engine.
template <typename Declaring>
struct RichTextBoxReadOnlyCapability {
    PropertyView<bool, RichTextBoxReadOnlyCapability<Declaring>> read_only;

    static void assign(RichTextBoxReadOnlyCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.read_only), std::move(incoming));
    }

    static bool read(const RichTextBoxReadOnlyCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        bool current = control.read_view(capability.read_only);
        return current;
    }
};

// Lines wrap at the box's width (WordWrap, the default); without wrapping a line is one row and the box scrolls horizontally.
template <typename Declaring>
struct RichTextBoxWordWrapCapability {
    PropertyCell<bool, RichTextBoxWordWrapCapability<Declaring>> word_wrap{true};

    static void assign(RichTextBoxWordWrapCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.word_wrap), incoming);
        if (!capability.word_wrap.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.word_wrap));
    }
};

// Whether Tab inserts a tab (AcceptsTab); off (the default), Tab moves the focus.
template <typename Declaring>
struct RichTextBoxAcceptsTabCapability {
    PropertyCell<bool, RichTextBoxAcceptsTabCapability<Declaring>> accepts_tab{};

    static void assign(RichTextBoxAcceptsTabCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.accepts_tab), incoming);
        if (!capability.accepts_tab.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.accepts_tab));
    }
};

// Whether the control bar is shown (the default). Its keys work without it. A change closes the heading menu.
template <typename Declaring>
struct RichTextBoxControlBarVisibleCapability {
    PropertyCell<bool, RichTextBoxControlBarVisibleCapability<Declaring>> control_bar_visible{true};

    static void assign(RichTextBoxControlBarVisibleCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.control_bar_visible), incoming);
        if (!capability.control_bar_visible.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.control_bar_visible));
    }
};

// Every RichTextBox capability, in the order the declaring class takes them.
template <typename Declaring>
struct RichTextBoxCapabilities : public RichTextBoxTextCapability<Declaring>,
                                 public RichTextBoxReadOnlyCapability<Declaring>,
                                 public RichTextBoxWordWrapCapability<Declaring>,
                                 public RichTextBoxAcceptsTabCapability<Declaring>,
                                 public RichTextBoxControlBarVisibleCapability<Declaring>,
                                 public FontCapability<Declaring> {
    RichTextBoxCapabilities() : FontCapability<Declaring>(FontSpec{FontRole::content, 12.0, 400, false}) {}
};

} // namespace gui_forms
